import { useState } from 'react';
import { motion } from 'motion/react';
import { Phone, CheckCircle } from 'lucide-react';
import { Helmet } from '@dr.pogodin/react-helmet';

const fadeUp = {
  hidden: { opacity: 0, y: 24 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.35, ease: 'easeOut' as const } },
} as const;

const stagger = {
  hidden: {},
  visible: { transition: { staggerChildren: 0.1 } },
} as const;

type FormState = 'idle' | 'submitting' | 'success' | 'error';

export default function ContactPage() {
  const [formState, setFormState] = useState<FormState>('idle');
  const [form, setForm] = useState({
    name: '',
    phone: '',
    email: '',
    service: '',
    message: '',
  });

  function handleChange(e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) {
    setForm((prev) => ({ ...prev, [e.target.name]: e.target.value }));
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    setFormState('submitting');
    try {
      const res = await fetch('/api/contact', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(form),
      });
      if (!res.ok) throw new Error('Failed');
      setFormState('success');
    } catch {
      setFormState('error');
    }
  }

  return (
    <>
      <Helmet>
        <title>Contact — Sparkle Clean</title>
        <meta name="description" content="Get a free quote or call (555) 867-5309 to schedule your house cleaning with Sparkle Clean." />
      </Helmet>

      {/* Hero */}
      <section className="bg-muted py-20">
        <div className="max-w-6xl mx-auto px-6">
          <motion.div variants={stagger} initial="hidden" animate="visible">
            <motion.p variants={fadeUp} className="text-primary font-semibold text-sm uppercase tracking-widest mb-3">
              Get in Touch
            </motion.p>
            <motion.h1 variants={fadeUp} className="font-heading text-4xl md:text-5xl font-bold text-foreground mb-4">
              Let's get your home sparkling
            </motion.h1>
            <motion.p variants={fadeUp} className="text-muted-foreground text-lg max-w-xl">
              Fill out the form below and I'll get back to you within 24 hours. Or just give me a call — I'd love to chat.
            </motion.p>
          </motion.div>
        </div>
      </section>

      {/* Content */}
      <section className="py-20 bg-background">
        <div className="max-w-6xl mx-auto px-6">
          <div className="grid grid-cols-1 lg:grid-cols-5 gap-12">

            {/* Sidebar info */}
            <motion.div
              variants={stagger}
              initial="hidden"
              whileInView="visible"
              viewport={{ once: true }}
              className="lg:col-span-2 flex flex-col gap-8"
            >
              {/* Call card */}
              <motion.div variants={fadeUp} className="bg-primary rounded-2xl p-8 text-primary-foreground">
                <div className="w-12 h-12 bg-primary-foreground/20 rounded-full flex items-center justify-center mb-5">
                  <Phone size={22} />
                </div>
                <h3 className="font-heading text-xl font-bold mb-2">Prefer to call?</h3>
                <p className="text-primary-foreground/80 text-sm mb-5 leading-relaxed">
                  Give me a ring and we can talk through what you need. I'm happy to answer any questions.
                </p>
                <a
                  href="tel:+15558675309"
                  className="inline-block bg-primary-foreground text-primary font-semibold px-6 py-3 rounded-full text-sm transition-all duration-200 hover:opacity-90 hover:shadow-md"
                >
                  (555) 867-5309
                </a>
              </motion.div>

              {/* What to expect */}
              <motion.div variants={fadeUp} className="bg-muted rounded-2xl p-8">
                <h3 className="font-heading text-lg font-bold text-foreground mb-4">What happens next?</h3>
                <ul className="flex flex-col gap-4">
                  {[
                    { step: '1', text: "I'll review your request and reach out within 24 hours." },
                    { step: '2', text: "We'll confirm the details and schedule a time that works for you." },
                    { step: '3', text: 'I show up and leave your home spotless.' },
                  ].map((item) => (
                    <li key={item.step} className="flex items-start gap-3">
                      <span className="shrink-0 w-6 h-6 rounded-full bg-primary text-primary-foreground text-xs font-bold flex items-center justify-center mt-0.5">
                        {item.step}
                      </span>
                      <p className="text-sm text-muted-foreground leading-relaxed">{item.text}</p>
                    </li>
                  ))}
                </ul>
              </motion.div>
            </motion.div>

            {/* Form */}
            <motion.div
              variants={stagger}
              initial="hidden"
              whileInView="visible"
              viewport={{ once: true }}
              className="lg:col-span-3"
            >
              {formState === 'success' ? (
                <motion.div
                  initial={{ opacity: 0, scale: 0.95 }}
                  animate={{ opacity: 1, scale: 1 }}
                  className="bg-muted rounded-2xl p-12 flex flex-col items-center text-center gap-5"
                >
                  <CheckCircle size={52} className="text-primary" />
                  <h2 className="font-heading text-2xl font-bold text-foreground">Message sent!</h2>
                  <p className="text-muted-foreground leading-relaxed max-w-sm">
                    Thanks for reaching out. I'll be in touch within 24 hours to get everything set up.
                  </p>
                  <a
                    href="tel:+15558675309"
                    className="text-primary font-semibold text-sm hover:underline"
                  >
                    Or call me now: (555) 867-5309
                  </a>
                </motion.div>
              ) : (
                <motion.form
                  variants={stagger}
                  onSubmit={handleSubmit}
                  className="bg-card border border-border/40 rounded-2xl p-8 shadow-sm flex flex-col gap-5"
                >
                  <motion.h2 variants={fadeUp} className="font-heading text-2xl font-bold text-foreground mb-1">
                    Request a Free Quote
                  </motion.h2>

                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
                    <motion.div variants={fadeUp} className="flex flex-col gap-1.5">
                      <label htmlFor="name" className="text-sm font-medium text-foreground">
                        Your Name <span className="text-accent">*</span>
                      </label>
                      <input
                        id="name"
                        name="name"
                        type="text"
                        required
                        value={form.name}
                        onChange={handleChange}
                        placeholder="Jane Smith"
                        className="border border-border rounded-lg px-4 py-3 text-sm bg-background text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/40 transition"
                      />
                    </motion.div>

                    <motion.div variants={fadeUp} className="flex flex-col gap-1.5">
                      <label htmlFor="phone" className="text-sm font-medium text-foreground">
                        Phone Number <span className="text-accent">*</span>
                      </label>
                      <input
                        id="phone"
                        name="phone"
                        type="tel"
                        required
                        value={form.phone}
                        onChange={handleChange}
                        placeholder="(555) 123-4567"
                        className="border border-border rounded-lg px-4 py-3 text-sm bg-background text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/40 transition"
                      />
                    </motion.div>
                  </div>

                  <motion.div variants={fadeUp} className="flex flex-col gap-1.5">
                    <label htmlFor="email" className="text-sm font-medium text-foreground">
                      Email Address
                    </label>
                    <input
                      id="email"
                      name="email"
                      type="email"
                      value={form.email}
                      onChange={handleChange}
                      placeholder="jane@example.com"
                      className="border border-border rounded-lg px-4 py-3 text-sm bg-background text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/40 transition"
                    />
                  </motion.div>

                  <motion.div variants={fadeUp} className="flex flex-col gap-1.5">
                    <label htmlFor="service" className="text-sm font-medium text-foreground">
                      Service Needed
                    </label>
                    <select
                      id="service"
                      name="service"
                      value={form.service}
                      onChange={handleChange}
                      className="border border-border rounded-lg px-4 py-3 text-sm bg-background text-foreground focus:outline-none focus:ring-2 focus:ring-primary/40 transition"
                    >
                      <option value="">Select a service...</option>
                      <option value="standard">Standard Clean</option>
                      <option value="deep">Deep Clean</option>
                      <option value="move">Move-In / Move-Out</option>
                      <option value="recurring">Recurring Service</option>
                      <option value="unsure">Not sure yet</option>
                    </select>
                  </motion.div>

                  <motion.div variants={fadeUp} className="flex flex-col gap-1.5">
                    <label htmlFor="message" className="text-sm font-medium text-foreground">
                      Anything else I should know?
                    </label>
                    <textarea
                      id="message"
                      name="message"
                      rows={4}
                      value={form.message}
                      onChange={handleChange}
                      placeholder="Home size, pets, special requests..."
                      className="border border-border rounded-lg px-4 py-3 text-sm bg-background text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/40 transition resize-none"
                    />
                  </motion.div>

                  {formState === 'error' && (
                    <p className="text-sm text-accent">Something went wrong. Please try again or call (555) 867-5309.</p>
                  )}

                  <motion.button
                    variants={fadeUp}
                    type="submit"
                    disabled={formState === 'submitting'}
                    className="bg-primary text-primary-foreground font-semibold px-8 py-4 rounded-full transition-all duration-200 hover:opacity-90 hover:shadow-md disabled:opacity-60 disabled:cursor-not-allowed"
                  >
                    {formState === 'submitting' ? 'Sending...' : 'Send My Request'}
                  </motion.button>
                </motion.form>
              )}
            </motion.div>
          </div>
        </div>
      </section>
    </>
  );
}

